pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash) public {
        vm.deal(address(this), 2 ether);
        vm.deal(address(c), 1 ether);
        // Fund the contract with initial 1 ether (already done in constructor) plus extra for payout
        // The constructor requires 1 ether on deploy, so we need to send 1 ether to c first
        // Actually, deploy already pays 1 ether; we need 2 ether balance for settle to work
        // So we send another 1 ether to c
        (bool success, ) = address(c).call{value: 1 ether}("");
        require(success);

        vm.deal(address(this), 2 ether); // refill

        c.lockInGuess{value: 1 ether}(hash);

        // Read the stored guess for msg.sender (the test contract)
        (uint blockNum, bytes32 storedGuess) = c.guesses(address(this));

        // The general property: after lockInGuess, the stored guess MUST equal the original hash
        // In the reference, guesses[msg.sender].guess == hash
        // In the mutant, guesses[msg.sender].guess == keccak256(abi.encodePacked(hash))
        assertTrue(storedGuess == hash);
    }
}

